-- ============================================================================
-- EC10: Farm-ins, Farm-outs & Asset Valuation joins the catalogue in the
-- Economics & Commercial module. AN ENGINE COURSE: there is no Suite app; the
-- practicals run in the course's own calculator panels.
--
-- Catalogue row (module 'economics'; path_order 75; prereq_slug NULL,
-- the lead's decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/farmout/gen_course.py
-- from the ENGINE'S OWN RUN (farmout_capstone.mjs through the vendored
-- engines/economics/farmout.js, petrolord-engines 6626465), which it refuses to
-- write unless fields.json carries exactly that run's values and the tolerance
-- gradedTolerance.js derives. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries the
-- route /dashboard/apps/farmout.
--
-- WHAT IS GRADED. OGBAKU (Associate) grades what the farminee and the farmor
-- pay for one well, the promote ratio, the carry, the consideration and the
-- equivalent working interest; UMUNZE (Professional) grades a payment under a
-- gross-cost cap exceeded, a payment under a carry cap exceeded, the
-- farminee's EMV, the break-even share and chance and the consent fee; AKPUGO
-- (Expert) grades the survey's EVII, a posterior chance of success, the risked
-- value per percent, a price-to-value ratio, a development carry balance and a
-- back-in refund. Every value is a return value of the engine, identical under
-- every reading the engine states and never a Monte Carlo draw, and the data it
-- was run on is in the case file the prompt names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('farmout', 'Farm-ins, Farm-outs & Asset Valuation', 'economics', 75, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'farmout', 'beginner', 'associate',
  'OGBAKU, a farm-out on the Ogbaku licence (synthetic)',
  'The deal and what it costs',
  'OGBAKU, a farm-out on the Ogbaku licence (synthetic). One case file comes with this capstone: ogbaku_case.json carries one call under the key earning; paste it into the earning calculator. The parties are OGB 60.25 percent, NKW 39.75 percent; OGB is the farmor and IHE (Ihembosi Resources (synthetic)) the farminee. The earning events: Ogbaku-1 exploration well: gross cost 37650000.5, IHE pays 44 percent to earn 31.75 percent, no cap (cap none). Vesting is per-event and 1 of 1 event is completed (eventsCompleted). IHE pays a cash bonus of 1250000.75 and reimburses 31.75 percent of 8430000.4 of past costs (pastCosts). No value depends on any of the readings the engine states (every cost at the valuation date, the day count of reg. 19(7), the ninetieth surcharge day, how a simple-interest uplift is paid) or on a Monte Carlo draw, and every term a value needs is stated in the case file: the engine holds no default for any of them. Report six values: what IHE pays of the Ogbaku-1 well; what OGB pays of it; the promote ratio of the event; the carry; the consideration to OGB; and IHE''s equivalent working interest in percent. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ogbaku_ihe_well_payment', 'label','What IHE pays of the Ogbaku-1 well', 'unit','USD', 'expected',16566000.22, 'tol',5e-07),
    jsonb_build_object('key','ogbaku_ogb_well_payment', 'label','What OGB pays of the Ogbaku-1 well', 'unit','USD', 'expected',6118125.08125, 'tol',5e-07),
    jsonb_build_object('key','ogbaku_promote_ratio', 'label','The promote ratio of the Ogbaku-1 event', 'unit','ratio', 'expected',1.3858267716535433, 'tol',5e-07),
    jsonb_build_object('key','ogbaku_carry', 'label','The carry of the Ogbaku-1 event', 'unit','USD', 'expected',4612125.061250001, 'tol',5e-07),
    jsonb_build_object('key','ogbaku_consideration', 'label','The consideration to OGB', 'unit','USD', 'expected',8538650.938250002, 'tol',5e-07),
    jsonb_build_object('key','ogbaku_equivalent_wi_pct', 'label','IHE''s equivalent working interest', 'unit','percent', 'expected',54.429019455125896, 'tol',5e-07)
  )
),
(
  'farmout', 'intermediate', 'professional',
  'UMUNZE, a drill-to-earn farm-out on the Umunze licence (synthetic)',
  'Caps, vesting, value and the fee',
  'UMUNZE, a drill-to-earn farm-out on the Umunze licence (synthetic). One case file comes with this capstone: umunze_case.json carries three calls under the keys earning, deal and fee; paste it into the deal calculator, whose views each read the key they need. The parties are UMZ 65 percent, ORJ 35 percent; UMZ is the farmor and AMG (Amaigbo Energy (synthetic)) the farminee. The earning events: Umunze-1 exploration well: gross cost 52340000.25, AMG pays 42 percent to earn 24 percent, the promote applies to the first 48000000 of cost (cap gross-cost), the excess paid by the post-deal interests (overrunRule post-deal-interests); Umunze-2 appraisal well: gross cost 31275000.4, AMG pays 38.5 percent to earn 12.5 percent, the carry is held at 550000.5 (cap carry-amount). Vesting is all-events and 2 of 2 events are completed (eventsCompleted). AMG pays a cash bonus of 1875000.25 and reimburses 24 percent of 14300000 of past costs (pastCosts). The deal is valued on the Umunze prospect with a chance of success of 22.5 percent, an exploration well of 44650000.75 on a success and 39120000.4 as a dry hole, and a success-case value of 318400000.5 at 100 percent, stated at the valuation date (successValue npv): AMG pays 42 percent of the well to earn 24 percent; the promote applies to the first 42000000 of cost (cap gross-cost), the excess paid by the post-deal interests (overrunRule post-deal-interests); a cash bonus of 1875000.25; 24 percent of 14300000 of past costs reimbursed; the farmor pays assignor fees of 618400.25 (assignorFees). The assignment is of a PPL under basis nuprc-2024-r19, intraGroup false, on a value of the transaction of 6437500.6 (contract-amount), notified on 2029-03-02 and paid on 2029-05-14. No value depends on any of the readings the engine states (every cost at the valuation date, the day count of reg. 19(7), the ninetieth surcharge day, how a simple-interest uplift is paid) or on a Monte Carlo draw, and every term a value needs is stated in the case file: the engine holds no default for any of them. Report six values: what AMG pays of the Umunze-1 well; what UMZ pays of the Umunze-2 well; AMG''s EMV farming in on the Umunze prospect; the share of the well AMG can pay at its break-even promote, in percent; AMG''s break-even chance of success, in percent; and the consent fee. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','umunze_well1_amg_payment', 'label','What AMG pays of the Umunze-1 well', 'unit','USD', 'expected',21201600.06, 'tol',5e-07),
    jsonb_build_object('key','umunze_well2_umz_payment', 'label','What UMZ pays of the Umunze-2 well', 'unit','USD', 'expected',8363374.614, 'tol',5e-07),
    jsonb_build_object('key','umunze_amg_emv', 'label','AMG''s EMV farming in on the Umunze prospect', 'unit','USD', 'expected',-4959060.393700002, 'tol',5e-07),
    jsonb_build_object('key','umunze_breakeven_share_pct', 'label','The share of the well AMG can pay at its break-even promote', 'unit','percent', 'expected',29.530023247226225, 'tol',5e-07),
    jsonb_build_object('key','umunze_amg_breakeven_chance_pct', 'label','AMG''s break-even chance of success', 'unit','percent', 'expected',29.15017270460909, 'tol',5e-07),
    jsonb_build_object('key','umunze_consent_fee', 'label','The consent fee on the Umunze assignment', 'unit','USD', 'expected',450625.042, 'tol',5e-07)
  )
),
(
  'farmout', 'advanced', 'expert',
  'AKPUGO, a farm-out on the Akpugo licence (synthetic)',
  'Information, price and after the farm-in',
  'AKPUGO, a farm-out on the Akpugo licence (synthetic). One case file comes with this capstone: akpugo_case.json carries four calls under the keys information, price, devCarry and backIn; paste it into the valuation calculator. The parties are AKP 72.5 percent, OBR 27.5 percent; AKP is the farmor and EZI the farminee. The Akpugo prospect has a chance of success of 18.5 percent, an exploration well of 51380000.5 on a success and 45260000.75 as a dry hole, and a success-case value of 402750000.25 at 100 percent, stated at the valuation date (successValue npv); the deal: EZI pays 46 percent of the well to earn 29.5 percent; no cap (cap none); a cash bonus of 2150000.5; 29.5 percent of 9840000 of past costs reimbursed; the farmor pays assignor fees of 312500.25 (assignorFees). A seismic survey costing 1650000.5 returns one of two signals: strong amplitude with a 72.5 percent chance given success and 21.3 percent given a dry hole; weak amplitude with a 27.5 percent chance given success and 78.7 percent given a dry hole; the side valued is the farminee. A 29.5 percent interest is priced on the risked basis at a stated price of 11240000.5. After a farm-in of 29.5 percent, EZI carries 60 percent of AKP''s development cost share, with a compound uplift of 7.5 percent a year (uplift compound), recovered from 55 percent of AKP''s share of each year''s entitlement (recoverFromPct); flows are discounted at 0.1 to 2030. AKP holds a back-in to 50 percent after the same farm-in, basis contract, refunding only the development and production costs (refundableKinds), paid upfront (refundForm). No value depends on any of the readings the engine states (every cost at the valuation date, the day count of reg. 19(7), the ninetieth surcharge day, how a simple-interest uplift is paid) or on a Monte Carlo draw, and every term a value needs is stated in the case file: the engine holds no default for any of them. Report six values: the survey''s EVII to EZI; the chance of success after the strong amplitude signal, in percent; the risked value per percent of working interest; the stated price over the risked value, per percent; the development carry balance carried out of 2035; and the back-in refund OBR receives. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','akpugo_ezi_evii', 'label','The survey''s EVII to EZI', 'unit','USD', 'expected',7596515.0435426915, 'tol',5e-07),
    jsonb_build_object('key','akpugo_strong_posterior_pct', 'label','The chance of success after the strong amplitude signal', 'unit','percent', 'expected',43.586702196802285, 'tol',5e-07),
    jsonb_build_object('key','akpugo_risked_value_per_pct', 'label','The risked value per percent of working interest', 'unit','USD', 'expected',281165.493425, 'tol',5e-07),
    jsonb_build_object('key','akpugo_price_to_value', 'label','The stated price over the risked value, per percent', 'unit','ratio', 'expected',1.3551341647951192, 'tol',5e-07),
    jsonb_build_object('key','akpugo_2035_carry_balance', 'label','The development carry balance carried out of 2035', 'unit','USD', 'expected',61235569.92884742, 'tol',5e-07),
    jsonb_build_object('key','akpugo_backin_refund_to_obr', 'label','The back-in refund OBR receives', 'unit','USD', 'expected',22328311.42883772, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
